/**********************************************************************************************************
This SAS program generates the sample used in the paper, titled "Facial Structure and Achievement Drive: Evidence from Financial Analysts"
The input data include: 
1) the raw data downloaded from CBAS;
2) the raw data downloaded from CSMAR;
3) the manually collected and cleaned data for analysts' facial width-to-height ratio (fWHR), analysts' ages, titles and firms' R&D expenses. 
The program include: 
1) Variable construction using the main regression analysis;
2) Variable construction for the subsample analysis.

data forecast;
set fwhr.forecast;/*Annual earnings forecasts from CBAS in December 2015*/
if 2004<=year(fpenddt)<=2014;
eyear=year(fpenddt);
ayear=year(anndats);
n=_n_;
andat=anndats;
fendt=fpenddt;
andat_act=anndats_act;
format andat fendt andat_act yymmdd10.;
i=1;
do while (kscan(a_code,i,'/' )^='');
a_code1=kscan(a_code,i,'/');
output;
i+1;
end;

proc import out=actual
datafile="[redacted-path-ecc03db8733a]" /*the dataset including actual earnings from CBAS*/
dbms=xlsx replace;
run;

data actual;
set actual;
format fpenddt yymmdd10.;
run;


proc sql;
create table forecast as 
select a.*,b.eps_act
from forecast a 
left join actual  b 
on a.s_code=b.s_code and a.fpenddt=b.fpenddt;

proc sql;
create table price as
select distinct a.s_code,a.andat,b.trddt,b.clsprc as price,(a.andat-input(b.trddt,yymmdd10.)) as diff,min(a.andat-input(b.trddt,yymmdd10.))  as first
from forecast a 
left join fwhr.price b /*the dataset including daily stock price from CSMAR*/
on a.s_code=b.stkcd and a.andat between input(b.trddt,yymmdd10.)+2 and input(b.trddt,yymmdd10.)+20
group by a.s_code,a.andat;
quit;

data price;
set price;
if diff eq first;
drop diff first;

proc import out=ind
datafile='[redacted-path-1a8f2c25688f]'/*dataset including industry code from CSMAR*/
dbms=dbf replace;
run;

data ind;
set ind;
if substr(accper,6,2) ="12";
if Typrep="A";
run;

proc sql;
create table forecast as 
select a.*,b.indcd 
from forecast a 
left join ind  b 
on a.s_code=b.stkcd and eyear=input(substr(accper,1,4),best12.);
quit;

data forecast;
set forecast;
ind=substr(indcd,1,1);
if substr(indcd,1,1)='C' then ind=indcd;
if ind=' ' then delete;
run;

data basic;
set fwhr.basic;/*dataset including analysts' basic information from CBAS and manual collection*/
gender=(sex='ÄÐ');
if kindex(high_degree,'Ë¶Ê¿') gt 0 or kindex(high_degree,'²©Ê¿') gt 0 then postgraduate=1;else postgraduate=0;
run;


proc sql;
create table forecast as 
select *
from forecast a 
left join basic b 
on a.a_code1=b.a_code;
quit;

data forecast;
set forecast;
age=ayear-birth_year;

/*Winsorize continous variables*/

%include "[redacted-path-bef23e322d90]";
%winsor(dsetin=forecast, dsetout=forecast,byvar=none, vars=absafep lagabsfep elaps fnum broker exp numcompany numind age,  type=winsor, pctl=1 99);

proc import out=brokerassets
datafile="[redacted-path-f3e325003b15]" /*dataset including financial information of brokerage firms from CBAS*/
dbms=excel replace;
run;

proc sort data=brokerassets;
by b_code date source;
run;

proc sort data=brokerassets nodupkey;
by b_code date;
run;

proc sql;
create table forecast  as
select a.*,b.t_assets as lagbrokerassets
from forecast a
left join brokerassets b
on a.b_code=b.b_code and a.ayear=year(b.date)+1;
quit;

proc sql;
create table forecast as 
select a.*,b.highstatus
from forecast a 
left join fwhr.title b /*fwhr.title is a manually cleaned dataset including analysts' high/low titles*/
on kcompress(kstrip(a.a_code1))=kcompress(kstrip(b.a_code))
   and a.andat between b.startdate and b.enddate;
quit;

proc sort data=forecast ;
by s_code a_code1 andat  descending highstatus;
run;

proc sort data=forecast nodupkey;
by s_code a_code1 andat eyear;
run;

data forecast;
set forecast;
if highstatus=. then highstatus=0;
run;

proc import out=fsba
datafile='[redacted-path-de84bbcb7c23]'/*dataset including financial data from balance sheet of listed firms from CSMAR*/
dbms=dbf replace;
run;


proc import out=fscf
datafile='[redacted-path-4408ce86000d]'/*dataset includingfinancial data from cash flow statement of listed firms from CSMAR*/
dbms=dbf replace;
run;

data fsba;
set fsba;
if substr(accper,6,2) eq '12';
if typrep='A';
year=substr(accper,1,4)+0;
run;

proc sql;
create table fin as 
select a.stkcd,a.accper,a.typrep, a.year, b.C001000000/a.A004000000 as cfoat
from fsba a left join fscf b
on a.stkcd=b.stkcd and a.accper=b.accper and a.typrep=b.typrep;
quit;

proc sql;
create table vola5 as 
select distinct a.stkcd,a.accper,a.year,std(b.cfoat) as cfvol
from fin a left join fin b 
on a.stkcd=b.stkcd and a.year-b.year>0 and a.year-b.year<=5 
group by a.stkcd,a.year;
quit;


proc sql;
create table forecast as
select a.*,b.cfvol
from forecast a left join vola5 b
on a.s_code=b.stkcd and a.ayear=b.year+1;

proc import out=ipo
datafile='[redacted-path-0f31edbb4efc]'/*dataset including IPO characteristics from CSMAR*/
dbms=excel replace;
run;


proc sql;
create table forecast 
as select a.*,ayear-year(input(listdt,yymmdd10.))+1 as firmage
from forecast a left join ipo b 
on a.s_code=b.stkcd ;
quit;

data forecast;
set forecast;
if firmage le 5 then cfvol=.;
run;

proc sql;
create table forecast as
select a.*,b.rd
from forecast a left join fwhr.rd b /*fwhr.rd includes mannually cleaned R&D expense of listed firms,raw datasets are from CSMAR*/
on a.s_code=b.stkcd and a.ayear=b.year;
quit;

data forecast;
set forecast;
drd=(rd gt 0);
run;

proc sql;
create table coverage as 
select distinct s_code,ayear,a_code1
from forecast a ;
quit;


proc sql;
create table coverage as 
select *,count(a_code1) as cover
from coverage a 
group by s_code,ayear;
quit;

proc sort data=coverage  nodupkey;
by s_code ayear;
run;


proc sql;
create table forecast 
as select a.*,b.cover as coverage
from forecast a
left join coverage b
on a.s_code=b.s_code and a.ayear=b.ayear+1;
quit;

proc sql;
create table forecast as
select a.*,b.bull
from forecast a 
left join fwhr.mktsentiment b /*dataset including whether Shanghai Composite Index return exceeds one-year risk-free rate, raw datasets are from CSMAR*/
on a.ayear=b.year;
quit;

/* Select the sample*/

data forecast;
set forecast;
/*drop forecasts issued by a group of analysts*/
if kindex(a_code,"/") gt 0 then delete;
/*drop forecasts issued less than 30 days before earnings announcement*/
if andat_act-andat>30;
run;

/*keep most recent forecast before earnings announcement*/
proc sort data=forecast;by s_code eyear a_code1 descending andat;run;

proc sort data=forecast nodupkey;by s_code eyear a_code1;run;
